class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")
        if customer not in self._customers:
            raise KeyError(customer)

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "queued",
        }
        return ticket_id

    def next_ticket(self) -> int | None:
        queued = (
            (ticket_id, ticket)
            for ticket_id, ticket in self._tickets.items()
            if ticket["state"] == "queued"
        )
        selected = min(
            queued,
            key=lambda item: (
                not self._customers[item[1]["customer"]],
                -self.PRIORITIES.index(item[1]["priority"]),
                item[0],
            ),
            default=None,
        )
        if selected is None:
            return None

        ticket_id, ticket = selected
        ticket["state"] = "in progress"
        return ticket_id

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["state"] = "queued"
